import{_ as i,C as n,o as m,c as l,a2 as e,j as t,a as o,E as s}from"./chunks/framework.Dx-TCpNt.js";const _=JSON.parse('{"title":"KomaYomi — Manga Learner ドキュメント","titleTemplate":false,"description":"KomaYomi（Manga Learner）ドキュメント — 漫画で言語を学び、ノートを取る。日中英の比較リーディング、コマ検出、位置合わせ、注釈に対応。","frontmatter":{"layout":"home","titleTemplate":false,"description":"KomaYomi（Manga Learner）ドキュメント — 漫画で言語を学び、ノートを取る。日中英の比較リーディング、コマ検出、位置合わせ、注釈に対応。","title":"KomaYomi — Manga Learner ドキュメント","hero":{"name":"KomaYomi","text":"Manga Learner","tagline":"日本語はすべて漫画から学んだ~","image":{"src":"/assets/screenshots/hero-real-library.png","alt":"実際のライブラリを使った3言語の比較リーダー。漫画の絵はぼかし処理済み"},"actions":[{"theme":"brand","text":"はじめる","link":"/ja/guide/introduction"},{"theme":"alt","text":"データ形式","link":"/ja/data-format"}]},"features":[{"title":"まずコマから","details":"XYカットによる自動検出に加え、手描き、結合、番号付け、再利用できるレイアウトテンプレート。コマ数が一致する場合、以前の注釈は再マッピングされます。"},{"title":"複数言語を比較","details":"並べて表示または重ね表示、言語ごとのマスク、ホイールズームとパン、さらにページ／コマ／アンカー／グリッドの位置合わせと再利用できるプリセット。"},{"title":"持ち運べるノート","details":"ページ単位またはコマ単位の Markdown ノート、タグ、出典、スクラッチパッド、全文検索、そして LLM に貼り付けるためのワンクリック「コンテキストをコピー」。"},{"title":"持ち出せる出力","details":"画像フォルダ付きの HTML または単一の埋め込みファイルとしてエクスポートし、ページ／コマ／コラージュの PNG を書き出し、すべてを `.mnproj` プロジェクトとして移せます。"}]},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md","lastUpdated":1794821397000}'),d={name:"ja/index.md"};function p(c,a,h,g,u,f){const r=n("Badge");return m(),l("div",null,[a[4]||(a[4]=e('<h2 id="komayomi-とは" tabindex="-1">KomaYomi とは？ <a class="header-anchor" href="#komayomi-とは" aria-label="Permalink to &quot;KomaYomi とは？&quot;">​</a></h2><p>KomaYomi（<strong>Manga Learner</strong>）は、漫画で言語を学び、ノートを取るための<strong>ローカル Web アプリケーション</strong>です。同じ漫画の日本語・中国語・英語版を並べて読み比べ、その場でノートを取れます。ページ画像は <code>raw/</code> フォルダに置いたままで、コマ、ノート、タグ、位置合わせのオフセット、注釈はすべて <code>data/</code> 以下のプレーンな JSON に保存されます。エクスポートしない限り、データがマシンの外に出ることはありません。</p><p>著作権のある素材を配布するためではなく、学習や翻訳レビューのために設計されています。自分のスキャンを用意し、アプリにフォルダを指定して、1ページずつ作業してください。</p><h2 id="現状の概要" tabindex="-1">現状の概要 <a class="header-anchor" href="#現状の概要" aria-label="Permalink to &quot;現状の概要&quot;">​</a></h2><p>KomaYomi は <strong>1.0.1</strong> です。このドキュメントでは、現在存在する機能と計画中の機能を区別して説明します。</p><div class="status-list"><div><strong>現在動作するもの</strong> — 複数作品のルートを含むライブラリのスキャン、XYカットによるコマ検出、手動でのコマ編集、コマの分割と、1–10 のクイック位置・右クリック移動に対応した番号の手動並べ替え、コマのグループ化とページ版履歴、サイドバーのページ一覧 3 表示（2 列サムネイル、1 列サムネイル、言語とノート数付きのリスト）、コマ／レイアウトテンプレート、アンカーと引き出し線付きのベクター注釈、マスクと4種類の位置合わせモードを備えた比較リーダー、言語ごとにページ全体を並べ、連動／独立のズームとパンを切り替えられる原版ビュー、コマ ID による深リンク付きのコマ詳細ビュー（比較リーダーの行を余白も含めてダブルクリックすると開きます）、詳細ビューでのセッション限りの言語別位置合わせ、ページ・話をまたぐ前のコマ／次のコマ、集中モード、編集／閲覧（読み取り専用）モード、検索と単一エディターでの編集に対応した Markdown ノート、ページ／コマ単位の種類付きノート（背景知識・単語・つぶやき、有効な言語ごとに1種類、カスタム種類は `data/library.json` に保存、絞り込み・グループ化・種類別の追加に対応）、6つの初回ステップと入口を備えたスタート画面、注釈を既定で焼き込む HTML / PNG / PDF（印刷）/ Word エクスポート、バックアップ ZIP と定期的な自動バックアップ、キャッシュ管理、WebDAV／ネットワークターゲットへのアップロード、オンデマンド LRU キャッシュとオフライン書き込みキューを備えた WebDAV／ネットワーク画像ソース、スキーマ検証付きのアトミックなページ保存と `.bak` ローテーション・同時書き込みロック、`.mnproj` プロジェクトのエクスポート／インポート、CLI バッチツール。</div><div><strong>計画中</strong> — 語彙リストのエクスポート。アプリ内での画像形式変換（名前変更と分割は前処理にあります）。完全なネイティブモバイルアプリ（レスポンシブな Web UI は狭いウィンドウでも動作します）。より広範な統合テスト。</div></div>',6)),t("p",null,[a[0]||(a[0]=o("このサイトで ",-1)),s(r,{type:"warning",text:"予定"}),a[1]||(a[1]=o(" と表示されているものは",-1)),a[2]||(a[2]=t("strong",null,"まだ実装されていません",-1)),a[3]||(a[3]=o("。コードにない挙動をページが説明している場合は、この注記を優先し、その機能は利用できないものと考えてください。",-1))]),a[5]||(a[5]=e('<h2 id="komayomi-の-4-つのリポジトリ" tabindex="-1">KomaYomi の 4 つのリポジトリ <a class="header-anchor" href="#komayomi-の-4-つのリポジトリ" aria-label="Permalink to &quot;KomaYomi の 4 つのリポジトリ&quot;">​</a></h2><p>このサイトが扱うのはデスクトップ完全版です。同じプロジェクトには他に 3 つの形態があります。</p><ul><li><a href="https://github.com/PayayaKamo/KomaYomi" target="_blank" rel="noopener noreferrer">KomaYomi</a> — デスクトップ完全版（Electron とローカルサーバー）。このドキュメントの対象です。</li><li><a href="https://github.com/PayayaKamo/KomaYomi-online" target="_blank" rel="noopener noreferrer">KomaYomi-online</a> — ブラウザー専用版。<code>.mnproj</code> プロジェクトを開いて閲覧・注釈・エクスポートができ、サーバーは不要です。</li><li><a href="https://github.com/PayayaKamo/KomaYomi-mobile" target="_blank" rel="noopener noreferrer">KomaYomi-mobile</a> — Android / iOS 向けの React Native アプリ。HarmonyOS NEXT は現在プレースホルダーのみです。</li><li><a href="https://github.com/PayayaKamo/KomaYomi-docs" target="_blank" rel="noopener noreferrer">KomaYomi-docs</a> — このサイトのビルド成果物で、CI が push します。ドキュメントの編集はメインリポジトリで行ってください。</li></ul><p>各形態は同じページ JSON と <code>.mnproj</code> 形式を共有しており、作業内容は形態間で移せます。</p><h2 id="次に読む" tabindex="-1">次に読む <a class="header-anchor" href="#次に読む" aria-label="Permalink to &quot;次に読む&quot;">​</a></h2><ul><li>はじめてですか？ <a href="/KomaYomi-docs/ja/guide/introduction">はじめに</a> を読んでから <a href="/KomaYomi-docs/ja/guide/installation">インストールと起動</a> へ。</li><li>全体像を知りたい？ <a href="/KomaYomi-docs/ja/concepts">基本概念</a> から始めてください。</li><li>JSON を扱う、プラグインを書く？ <a href="/KomaYomi-docs/ja/data-format">データ形式</a> と <a href="/KomaYomi-docs/ja/extending">レイアウトテンプレートとプラグイン</a> へ。</li><li>ページが見つからない、エクスポートが壊れた？ <a href="/KomaYomi-docs/ja/faq">FAQ とトラブルシューティング</a> を見てください。</li></ul><div class="tip custom-block"><p class="custom-block-title">ドキュメントの言語</p><p>英語が主要な言語です。中国語訳は <code>/zh/</code>、日本語訳は <code>/ja/</code> にあります。各ページはそれぞれの状態を個別に示します。</p></div>',7))])}const b=i(d,[["render",p]]);export{_ as __pageData,b as default};
